"""Generate kbc.py (the Kemptville Home Hardware Building Centre edition) from the supplier-neutral master
supplier_connection.py. Every change is an explicit, asserted replacement or insertion, so the master stays the one
governed source and this file documents exactly what the KBC edition changes. Run: python3 make_kbc.py && python3 kbc.py"""
import os

HERE = os.path.dirname(os.path.abspath(__file__))
s = open(f"{HERE}/supplier_connection.py").read()


def R(a, b, cnt=1):
    global s
    assert s.count(a) == cnt, (a[:80], s.count(a))
    s = s.replace(a, b)


def INS_AFTER(anchor, text):
    global s
    assert s.count(anchor) == 1, anchor[:80]
    s = s.replace(anchor, anchor + text)


R('"""CalibraytAI — Supplier Connection, screen edition (supplier-neutral). Content from nbuild/build_neutral.py."""',
  '"""GENERATED by make_kbc.py from supplier_connection.py — do not edit by hand.\nCalibraytAI — Supplier Connection, Kemptville Home Hardware Building Centre (KBC) edition, 22 Oct 2026.\nNo concrete chapter and no other supplier’s content. KBC-named synthetic screens (sup/kshots)."""')
R("from deck import hook_page, calc_pages, Deck,", "from deck import hook_page, sponsor_concept, calc_pages, Deck,")
R('hook_page(d, nxt, "your store", "your contractor customers", "your quoting desk")', 'hook_page(d, nxt, "KBC", "your Pro Account contractors", "the KBC Pro Desk")')
R('A = f"{S}/nbuild/assets"', '''A = f"{S}/kbc/assets"
BR = f"{S}/deck/brand"
HHBC = img(f"{BR}/home-hardware-building-centre-lockup-1200dpi.png", 900, 95)  # official lock-up, HHSL Supplier Guide v3.1 p.4 (see brand/SHA256SUMS)''')
R('CH, CREDITS, credit, PHOTO = ns["CH"], ns["CREDITS"], ns["credit"], ns["PHOTO"]', '''CH, CREDITS, credit, PHOTO = ns["CH"], ns["CREDITS"], ns["credit"], ns["PHOTO"]
import copy
CH = copy.deepcopy(CH)
CREDITS[:] = [(k, "Serhat Tuğ", "Pexels") if k == "Chapter 07" else (k, w, x) for k, w, x in CREDITS]


def fix(n, key, old, new):
    c = next(x for x in CH if x["n"] == n)
    if isinstance(c[key], list):
        hits = [i for i, t in enumerate(c[key]) if old in t]
        assert hits, (n, key, old)
        for i in hits:
            c[key][i] = c[key][i].replace(old, new)
    else:
        assert old in c[key], (n, key, old)
        c[key] = c[key].replace(old, new)


# KBC: no concrete in the story (Joel, 22 Oct 2026); the store is KBC, its contractors are Pro Account customers.
fix(1, "story", "a concrete pour booked for Thursday", "a framing package to be delivered on Thursday")
fix(3, "story", "from the supplier they buy from most, and keeps the option to ask another.", "from KBC, where they hold a Pro Account, and keeps the option to ask another supplier.")
fix(4, "story", "At the Participating Building Supplier, the Supplier Representative is notified and opens the Harbour Lane request at the desk.", "At KBC, the Pro Desk is notified and opens the Harbour Lane request.")
fix(6, "story", "and arranges the concrete for the footings through its own Fulfillment Partner.", "and arranges the railing panels through its own Fulfillment Partner, a distribution centre.")
fix(6, "body", "such as a ready-mix plant for concrete", "such as a distribution centre or a truss, window or railing manufacturer")
fix(7, "story", "Rain is forecast for Thursday. The contractor moves the footing pour on the project schedule, and the supplier is asked to move the concrete with it.",
    "The railing panels for Harbour Lane will be a day late. KBC proposes a new delivery date with the reason, and the contractor accepts it from the site.")
fix(8, "story", "At the end of the quarter, the supplier looks back", "At the end of the quarter, KBC looks back")
for c in CH:
    for k in ("story", "headline", "sub", "title"):
        assert "concrete" not in c[k].lower(), (c["n"], k)
    for t in c["body"]:
        assert "concrete" not in t.lower(), (c["n"], t[:60])''')
